import esbuild from 'esbuild';
import fs from 'node:fs';
import { parseArgs } from 'node:util';
import envs from './envs.js';
import browserslistToEsbuild from 'browserslist-to-esbuild';
import { writeLanesStrings } from '../scripts/build_lanes_strings.js';

let args = parseArgs({options: {
  watch: { type: 'boolean' },
  stats: { type: 'boolean' }
}}).values;

// Lane Studio's strings are built with the code that reads them
writeLanesStrings();

const build = await esbuild.build({
  define: envs,
  minify: true,
  bundle: true,
  sourcemap: true,
  entryPoints: {
    'iD.min': './modules/id.js',
    'lanes.min': './modules/lanes/index.ts'
  },
  legalComments: 'none',
  logLevel: 'info',
  metafile: true,
  outdir: 'dist',
  target: browserslistToEsbuild(),
  loader: { '.DS_Store' : 'empty' },
  treeShaking: true,
})
.catch(() => process.exit(1));

if (args.stats) {
  fs.writeFileSync('./dist/esbuild.json', JSON.stringify(build.metafile, null, 2));
}
